function validate([root, k]) {
  if (!root.length || root[0] === null) return 'The tree needs at least 1 node.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => v < 1 || v > 10000)) return 'Every node value is between 1 and 10^4.';
  if (k < 1 || k > 10) return 'k is between 1 and 10.';
  return null;
}

