function countGreatEnoughNodes(root, k) {
  // For every node, list its whole subtree and count the smaller values directly.
  const collect = (node, out) => {
    if (node) {
      out.push(node.val);
      collect(node.left, out);
      collect(node.right, out);
    }
    return out;
  };
  let count = 0;
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    const values = collect(node, []);
    const smaller = values.filter(v => v < node.val).length;
    if (values.length >= k && smaller >= k) count++;
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return count;
}

