function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 12);
  const mode = rand();
  const constant = 1 + Math.floor(rand() * 10000);
  // Values are random over the full range, from a narrow range (many ties), all equal,
  // or mostly shrinking downwards so that many nodes beat their descendants.
  const value = parent => {
    if (mode < 0.3) return 1 + Math.floor(rand() * 10000);
    if (mode < 0.55) return 1 + Math.floor(rand() * 6);
    if (mode < 0.65) return constant;
    if (parent === null) return 5000 + Math.floor(rand() * 5001);
    return Math.max(1, Math.min(10000, parent - Math.floor(rand() * 40) + 8));
  };
  // Some trees start with a long downward chain, which makes deep paths.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: value(null), left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: value(nodes[i - 1].val), left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const pick = Math.floor(rand() * slots.length);
    const [parent, side] = slots[pick];
    slots[pick] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: value(nodes[parent].val), left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  const k = 1 + Math.floor(rand() * (large ? 10 : Math.min(10, Math.max(1, n - 1))));
  return [out, k];
}
